import sqlite3
import os
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        email TEXT NOT NULL,
        password_hash TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        department TEXT,
        active INTEGER DEFAULT 1
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        action TEXT,
        target_user TEXT,
        performed_by TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by department or role for directory listing.
    Requires valid session token (checked by upstream middleware)."""
    query_param = request.args.get('q', '')
    field = request.args.get('field', 'department')

    # Validate field to prevent injection into column names
    allowed_fields = ['department', 'role', 'username']
    if field not in allowed_fields:
        return jsonify({'error': 'Invalid field'}), 400

    # Build query - field is validated above, but q is user-controlled
    sql = f"SELECT username, email, department, role FROM users WHERE {field} LIKE '%{query_param}%' AND active = 1"

    try:
        db = get_db()
        results = db.execute(sql).fetchall()
        users = [dict(row) for row in results]

        # Log the search for compliance
        requester = request.headers.get('X-Authenticated-User', 'anonymous')
        db.execute(
            "INSERT INTO audit_log (action, target_user, performed_by) VALUES (?, ?, ?)",
            ('user_search', f'field={field},q={query_param[:50]}', requester)
        )
        db.commit()

        return jsonify({'results': users, 'count': len(users)})
    except sqlite3.Error as e:
        return jsonify({'error': 'Database error', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user profile by ID. Returns public fields only."""
    db = get_db()
    user = db.execute(
        "SELECT username, email, department, role FROM users WHERE id = ? AND active = 1",
        (user_id,)
    ).fetchone()
    if user is None:
        return jsonify({'error': 'User not found'}), 404
    return jsonify(dict(user))

@app.route('/api/users', methods=['POST'])
def create_user():
    """Admin endpoint to create users. Role check performed by gateway policy."""
    data = request.get_json()
    if not data or 'username' not in data or 'email' not in data:
        return jsonify({'error': 'Missing required fields'}), 400

    db = get_db()
    try:
        db.execute(
            "INSERT INTO users (username, email, password_hash, role, department) VALUES (?, ?, ?, ?, ?)",
            (data['username'], data['email'], data.get('password_hash', ''), 
             data.get('role', 'user'), data.get('department', ''))
        )
        db.commit()
        return jsonify({'status': 'created'}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username already exists'}), 409

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=os.environ.get('DEBUG', False))
